// scan.Mapper[*T] without reflection: maps columns to fields by index.
func proxyRequestScanMapper(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*ProxyRequest, error)) {
	// resolve the column positions once per query, not per row
	type target struct {
		idx int
		dst func(o *ProxyRequest) any
	}
	targets := make([]target, 0, 18)
	for i, col := range cols {
		switch col {
		case "id":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ID }})
		case "client_key_id":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ClientKeyID }})
		case "protocol":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.Protocol }})
		case "logical_model":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.LogicalModel }})
		case "state":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.State }})
		case "received_at":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ReceivedAt }})
		case "completed_at":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.CompletedAt }})
		case "selected_provider":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.SelectedProvider }})
		case "selected_upstream_model":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.SelectedUpstreamModel }})
		case "attempt_count":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.AttemptCount }})
		case "duration_ms":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.DurationMS }})
		case "error_code":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ErrorCode }})
		case "error_message":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ErrorMessage }})
		case "stats_disposition":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.StatsDisposition }})
		case "resolved_group_id":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ResolvedGroupID }})
		case "resolved_group_revision":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ResolvedGroupRevision }})
		case "resolved_plan_json":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.ResolvedPlanJSON }})
		case "selected_logical_model":
			targets = append(targets, target{i, func(o *ProxyRequest) any { return &o.SelectedLogicalModel }})
		}
	}

	return func(row *scan.Row) (any, error) {
			o := new(ProxyRequest)
			for _, t := range targets {
				row.ScheduleScanByIndex(t.idx, t.dst(o))
			}
			return o, nil
		}, func(v any) (*ProxyRequest, error) {
			return v.(*ProxyRequest), nil
		}
}

// FindProxyRequest retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindProxyRequest(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*ProxyRequest, error) {
	if len(cols) == 0 {
		return ProxyRequests.Query(
			sm.Where(ProxyRequests.Columns.ID.EQ(sqlite.Arg(IDPK))),
		).One(ctx, exec)
	}

	return ProxyRequests.Query(
		sm.Where(ProxyRequests.Columns.ID.EQ(sqlite.Arg(IDPK))),
		sm.Columns(ProxyRequests.Columns.Only(cols...)),
	).One(ctx, exec)
}

// ProxyRequestExists checks the presence of a single record by primary key
func ProxyRequestExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return ProxyRequests.Query(
		sm.Where(ProxyRequests.Columns.ID.EQ(sqlite.Arg(IDPK))),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after ProxyRequest is retrieved from the database
func (o *ProxyRequest) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = ProxyRequests.AfterSelectHooks.RunHooks(ctx, exec, ProxyRequestSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = ProxyRequests.AfterInsertHooks.RunHooks(ctx, exec, ProxyRequestSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = ProxyRequests.AfterUpdateHooks.RunHooks(ctx, exec, ProxyRequestSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = ProxyRequests.AfterDeleteHooks.RunHooks(ctx, exec, ProxyRequestSlice{o})

	}

	return err
}

// primaryKeyVals returns the primary key values of the ProxyRequest
func (o *ProxyRequest) primaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *ProxyRequest) pkEQ() dialect.Expression {
	return sqlite.Quote("proxy_requests", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the ProxyRequest
func (o *ProxyRequest) Update(ctx context.Context, exec bob.Executor, s *ProxyRequestSetter) error {
	v, err := ProxyRequests.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

